package dev.cazajefes;
import java.util.*;
import org.bukkit.*;
import org.bukkit.entity.*;
import org.bukkit.event.*;
import org.bukkit.event.entity.*;
import org.bukkit.persistence.PersistentDataType;
import org.bukkit.potion.*;
import org.bukkit.scheduler.BukkitTask;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.*;
final class MageCombat implements Listener {
 private static final class Mage {LivingEntity boss;BossCatalog.Definition definition;long ready,release,next;int phase,remaining;UUID target;Location mark;Mage(LivingEntity b,BossCatalog.Definition d){boss=b;definition=d;ready=System.currentTimeMillis()+18000;}}
 private record Healer(LivingEntity entity,LivingEntity parent){}
 private final CazaJefesPlugin plugin;private final Map<UUID,Mage> bosses=new HashMap<>();private final Map<UUID,Healer> healers=new LinkedHashMap<>();private final Map<UUID,Long> healReady=new HashMap<>();private final BukkitTask task;private UUID stormVictim;private double stormDamage;
 MageCombat(CazaJefesPlugin plugin){this.plugin=plugin;task=plugin.getServer().getScheduler().runTaskTimer(plugin,this::tick,5,5);}
 void track(LivingEntity boss,BossCatalog.Definition d){if(SpellVisuals.mage(boss.getType()))bosses.putIfAbsent(boss.getUniqueId(),new Mage(boss,d));}
 void healer(LivingEntity entity,LivingEntity parent){healers.put(entity.getUniqueId(),new Healer(entity,parent));healReady.putIfAbsent(parent.getUniqueId(),System.currentTimeMillis()+MageRules.HEAL_COOLDOWN);}
 boolean busy(UUID id){var mage=bosses.get(id);return mage!=null&&(mage.release>0||mage.remaining>0);}
 private Player target(LivingEntity boss){String focus=boss.getPersistentDataContainer().get(new NamespacedKey(plugin,"aggro_target"),PersistentDataType.STRING);if(focus!=null)try{Player p=Bukkit.getPlayer(UUID.fromString(focus));if(p!=null&&CombatGuard.eligible(p)&&p.getWorld().equals(boss.getWorld())&&p.getLocation().distanceSquared(boss.getLocation())<=576&&boss.hasLineOfSight(p))return p;}catch(IllegalArgumentException ignored){}var participants=BossParticipation.participants(boss);return boss.getWorld().getPlayers().stream().filter(p->CombatGuard.eligible(p)&&p.getLocation().distanceSquared(boss.getLocation())<=576&&boss.hasLineOfSight(p)).min(Comparator.comparingDouble(p->p.getLocation().distanceSquared(boss.getLocation())*(participants.contains(p.getUniqueId())?.5:1))).orElse(null);}
 private void tick(){long now=System.currentTimeMillis();heal(now);for(var it=bosses.entrySet().iterator();it.hasNext();){var mage=it.next().getValue();LivingEntity boss=mage.boss;if(!boss.isValid()||boss.isDead()){healReady.remove(boss.getUniqueId());it.remove();continue;}if(boss.isInvulnerable())continue;
  if(mage.release>0){if(now<mage.release){Player p=Bukkit.getPlayer(mage.target);if(p!=null)BossWarnings.send(p,Component.text("⚠ "+name(mage)+" · Cargando",NamedTextColor.LIGHT_PURPLE).decorate(TextDecoration.BOLD));CombatVisuals.signatureRing(mage.mark,mage.definition,3,16);continue;}mage.release=0;mage.remaining=storm(mage)?MageRules.RAYS:3;mage.next=Bukkit.getCurrentTick();}
  if(mage.remaining>0){if(Bukkit.getCurrentTick()>=mage.next){pulse(mage);mage.remaining--;mage.next=Bukkit.getCurrentTick()+20;if(mage.remaining==0){mage.ready=now+(storm(mage)?25000:18000);if(boss instanceof Spellcaster spell)spell.setSpell(Spellcaster.Spell.NONE);}}continue;}
  if(now<mage.ready||plugin.abilities.occupied(boss)||plugin.pillagers.charging(boss.getUniqueId())||plugin.archers.charging(boss.getUniqueId()))continue;Player player=target(boss);if(player==null)continue;mage.phase=BossStages.phase(boss);mage.target=player.getUniqueId();mage.mark=player.getLocation().clone();mage.release=now+2000;if(boss instanceof Mob mob)mob.getPathfinder().stopPathfinding();if(boss instanceof Spellcaster spell)spell.setSpell(Spellcaster.Spell.FANGS);BossWarnings.send(player,Component.text("⚠ "+name(mage)+" · ¡Busca cobertura!",NamedTextColor.LIGHT_PURPLE).decorate(TextDecoration.BOLD));boss.getWorld().playSound(boss.getLocation(),Sound.ENTITY_EVOKER_PREPARE_ATTACK,.8f,.7f);
 }}
 private static boolean storm(Mage mage){return mage.boss.getType()==EntityType.EVOKER&&mage.phase==3;}
 private static String name(Mage mage){return storm(mage)?"JUICIO DE LAS SEIS TORMENTAS":mage.phase==1?"GRILLETES DEL CONJURADOR":"RUNAS DE ENTROPÍA";}
 private void pulse(Mage mage){LivingEntity boss=mage.boss;Player p=Bukkit.getPlayer(mage.target);if(p==null||!CombatGuard.eligible(p)||!p.getWorld().equals(boss.getWorld())||p.getLocation().distanceSquared(boss.getLocation())>576||!boss.hasLineOfSight(p))return;
  if(storm(mage)){p.getWorld().strikeLightningEffect(p.getLocation());stormVictim=p.getUniqueId();stormDamage=MageRules.rayDamage(BossStages.phase(boss),BossRebirth.used(boss));try{AbilityDamage.hit(p,boss,stormDamage);}finally{stormVictim=null;}BossWarnings.send(p,Component.text("⚡ JUICIO DE LAS SEIS TORMENTAS · "+(7-mage.remaining)+"/6",NamedTextColor.GOLD).decorate(TextDecoration.BOLD));}
  else{CombatVisuals.signatureRing(mage.mark,mage.definition,3,24);if(p.getLocation().distanceSquared(mage.mark)<=9&&AbilityDamage.hit(p,boss,mage.definition.tier().damage*1.2)){BossEffects.apply(p,BossEffects.effect(PotionEffectType.WEAKNESS,60,0));BossEffects.apply(p,BossEffects.effect(mage.phase>=2?PotionEffectType.NAUSEA:PotionEffectType.SLOWNESS,60,0));}}boss.getWorld().playSound(boss.getLocation(),Sound.ENTITY_EVOKER_CAST_SPELL,.9f,1.2f);
 }
 private void heal(long now){for(var it=healers.entrySet().iterator();it.hasNext();){var h=it.next().getValue();LivingEntity unit=h.entity(),boss=h.parent();if(!unit.isValid()||unit.isDead()||!boss.isValid()||boss.isDead()){it.remove();continue;}if(boss.isInvulnerable()||!unit.getWorld().equals(boss.getWorld())||unit.getLocation().distanceSquared(boss.getLocation())>576||!unit.hasLineOfSight(boss)||boss.getHealth()>=boss.getMaxHealth()||now<healReady.getOrDefault(boss.getUniqueId(),0L))continue;healReady.put(boss.getUniqueId(),now+MageRules.HEAL_COOLDOWN);double amount=MageRules.healing(boss.getMaxHealth());var event=new EntityRegainHealthEvent(boss,amount,EntityRegainHealthEvent.RegainReason.CUSTOM);Bukkit.getPluginManager().callEvent(event);if(event.isCancelled()||!Double.isFinite(event.getAmount())||event.getAmount()<=0)continue;double before=boss.getHealth();boss.setHealth(Math.min(boss.getMaxHealth(),before+Math.min(amount,event.getAmount())));if(boss.getHealth()<=before)continue;unit.swingMainHand();var delta=boss.getEyeLocation().toVector().subtract(unit.getEyeLocation().toVector());for(int i=0;i<16;i++)CosmeticFX.emit(Particle.DUST,unit.getEyeLocation().add(delta.clone().multiply(i/15.0)),1,0,0,0,0,new Particle.DustOptions(Color.LIME,1.2f));Component text=Component.text("✦ "+boss.getName()+" ha recibido Hechizo de Cura · +"+String.format(Locale.ROOT,"%.1f",boss.getHealth()-before)+" de vida",NamedTextColor.GREEN).decorate(TextDecoration.BOLD);Set<UUID> audience=BossParticipation.participants(boss);for(Player p:boss.getWorld().getPlayers())if(p.getLocation().distanceSquared(boss.getLocation())<=1024)audience.add(p.getUniqueId());for(UUID id:audience){Player p=Bukkit.getPlayer(id);if(p!=null&&p.isOnline())p.sendMessage(text);}boss.getWorld().playSound(boss.getLocation(),Sound.BLOCK_AMETHYST_BLOCK_CHIME,.8f,1.5f);}}
 @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true)public void stormDamage(EntityDamageByEntityEvent e){if(stormVictim!=null&&e.getEntity().getUniqueId().equals(stormVictim))BossDeathVisuals.fixedBlastDamage(e,stormDamage);}
 @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true)public void nativeProjectile(ProjectileLaunchEvent e){if(e.getEntity().getShooter() instanceof Entity shooter&&busy(shooter.getUniqueId()))e.setCancelled(true);}
 @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true)public void nativeSpell(EntitySpellCastEvent e){if(busy(e.getEntity().getUniqueId()))e.setCancelled(true);}
 void stop(){task.cancel();for(var m:bosses.values())if(m.boss.isValid()&&m.boss instanceof Spellcaster spell)spell.setSpell(Spellcaster.Spell.NONE);bosses.clear();healers.clear();healReady.clear();}
}
